Go<pre><code>// GetServer ​获取​下​一个​服务器​
func (lb *RoundRobinLoadBalancer) GetServer(key string) *Server {
    lb.mu.Lock()
    defer lb.mu.Unlock()

    if len(lb.Servers) == 0 {
        return nil
    }

    if !lb.weighted {
        // ​非​加权​轮询​
        index := atomic.AddInt64(&amp;lb.currentIndex, 1) % int64(len(lb.Servers))
        return lb.Servers[index]
    }

    // ​实现​平滑​加权​轮询​（Smooth Weighted Round-Robin）
    totalWeight := 0
    var bestServer *Server

    // ​计算​总​有效​权重​，​并​为​每个​服务器​增加​当前​权重​
    for _, server := range lb.Servers {
        // ​确保​有效​权重​被​初始化​
        if server.EffectiveWeight == 0 {
            server.EffectiveWeight = server.Weight
        }
        // ​当前​权重​增加​有效​权重​
        server.CurrentWeight += server.EffectiveWeight
        totalWeight += server.EffectiveWeight

        // ​选择​当前​权重​最大​的​服务器​
        if bestServer == nil || server.CurrentWeight &gt; bestServer.CurrentWeight {
            bestServer = server
        }
    }

    // ​如果​找到​了​最佳​服务器​，​减少​其​当前​权重​
    if bestServer != nil {
        bestServer.CurrentWeight -= totalWeight
    }

    return bestServer
}
</code></pre>

Go<pre><code>// GetServer ​获取​连接数​最少​的​服务器​
func (lb *LeastConnectionsLoadBalancer) GetServer(key string) *Server {
    lb.mu.Lock()
    defer lb.mu.Unlock()

    // ​过滤​出​可用​的​服务器​
    availableServers := make([]*Server, 0)
    for _, server := range lb.Servers {
        if server.Weight &gt; 0 {
            availableServers = append(availableServers, server)
        }
    }

    if len(availableServers) == 0 {
        return nil
    }

    // ​找到​连接数​最少​的​服务器​
    var selectedServer *Server
    minValue := float64(1&lt;&lt;63 - 1)

    for _, server := range availableServers {
        connPtr := lb.connections[server]
        if connPtr == nil {
            var conn int64
            connPtr = &amp;conn
            lb.connections[server] = connPtr
        }
        connections := atomic.LoadInt64(connPtr)

        var currentValue float64
        if lb.weighted {
            // ​加权​最小​连接​：​考虑​权重​因素​
            if server.Weight &gt; 0 {
                // ​权重​越大​，​加权​值越​小​，​越​容易​被​选中​
                currentValue = float64(connections) / float64(server.Weight)
            } else {
                // ​如果​权重​为​0，​则​使用​最大值​，​确保​不会​被​选中​
                currentValue = float64(1&lt;&lt;63 - 1)
            }
        } else {
            // ​非​加权​最小​连接​
            currentValue = float64(connections)
        }

        // ​如果​当前​值​小于​最小值​，​选择​此​服务器​
        if currentValue &lt; minValue {
            minValue = currentValue
            selectedServer = server
        } else if currentValue == minValue &amp;&amp; selectedServer != nil {
            // ​如果​加权​值​相同​，​优先选择​权重​更​高​的​服务器​
            if server.Weight &gt; selectedServer.Weight {
                selectedServer = server
            }
        }
    }

    if selectedServer != nil {
        // ​增加​选中​服务器​的​连接数​
        atomic.AddInt64(lb.connections[selectedServer], 1)
        // ​同时​更新​Server​结构​体中​的​CurrentConnections​字​段​，​方便​外部​查看​
        atomic.AddInt32(&amp;selectedServer.CurrentConnections, 1)
    }

    return selectedServer
}

// ReleaseConnection ​释放​连接​
func (lb *LeastConnectionsLoadBalancer) ReleaseConnection(server *Server) {
    if server == nil {
        return
    }

    lb.mu.Lock()
    defer lb.mu.Unlock()

    if connPtr, exists := lb.connections[server]; exists &amp;&amp; atomic.LoadInt64(connPtr) &gt; 0 {
        atomic.AddInt64(connPtr, -1)
        // ​同时​更新​Server​结构​体中​的​CurrentConnections​字​段​
        if server.CurrentConnections &gt; 0 {
            atomic.AddInt32(&amp;server.CurrentConnections, -1)
        }
    }
}
</code></pre>

Go<pre><code>package socks5

import (
    "encoding/binary"
    "errors"
    "fmt"
    "io"
    "net"
)

/**
 * user: ZY
 * Date: 2020/11/24 15:38
 */

func main() {
    server, err := net.Listen("tcp", ":1080")
    if err != nil {
        fmt.Printf("Listen failed: %v\n", err)
        return
    }

    for {
        client, err := server.Accept()
        if err != nil {
            fmt.Printf("Accept failed: %v", err)
            continue
        }
        go process(client)
    }
}

func process(client net.Conn) {
    if err := Socks5Auth(client); err != nil {
        fmt.Println("auth error:", err)
        client.Close()
        return
    }

    target, err := Socks5Connect(client)
    if err != nil {
        fmt.Println("connect error:", err)
        client.Close()
        return
    }

    Socks5Forward(client, target)
}

func Socks5Auth(client net.Conn) (err error) {
    buf := make([]byte, 256)

    // ​读取​ VER ​和​ NMETHODS
    n, err := io.ReadFull(client, buf[:2])
    if n != 2 {
        return errors.New("reading header: " + err.Error())
    }

    ver, nMethods := int(buf[0]), int(buf[1])
    if ver != 5 {
        return errors.New("invalid version")
    }

    // ​读取​ METHODS ​列表​
    n, err = io.ReadFull(client, buf[:nMethods])
    if n != nMethods {
        return errors.New("reading methods: " + err.Error())
    }

    //​无需​认证​
    n, err = client.Write([]byte{0x05, 0x00})
    if n != 2 || err != nil {
        return errors.New("write rsp: " + err.Error())
    }

    return nil
}

func Socks5Connect(client net.Conn) (net.Conn, error) {
    buf := make([]byte, 256)

    n, err := io.ReadFull(client, buf[:4])
    if n != 4 {
        return nil, errors.New("read header: " + err.Error())
    }

    ver, cmd, _, atyp := buf[0], buf[1], buf[2], buf[3]
    if ver != 5 || cmd != 1 {
        return nil, errors.New("invalid ver/cmd")
    }

    addr := ""
    switch atyp {
    case 1:
        n, err = io.ReadFull(client, buf[:4])
        if n != 4 {
            return nil, errors.New("invalid IPv4: " + err.Error())
        }
        addr = fmt.Sprintf("%d.%d.%d.%d", buf[0], buf[1], buf[2], buf[3])

    case 3:
        n, err = io.ReadFull(client, buf[:1])
        if n != 1 {
            return nil, errors.New("invalid hostname: " + err.Error())
        }
        addrLen := int(buf[0])

        n, err = io.ReadFull(client, buf[:addrLen])
        if n != addrLen {
            return nil, errors.New("invalid hostname: " + err.Error())
        }
        addr = string(buf[:addrLen])

    case 4:
        return nil, errors.New("IPv6: no supported yet")

    default:
        return nil, errors.New("invalid atyp")
    }

    n, err = io.ReadFull(client, buf[:2])
    if n != 2 {
        return nil, errors.New("read port: " + err.Error())
    }
    port := binary.BigEndian.Uint16(buf[:2])

    destAddrPort := fmt.Sprintf("%s:%d", addr, port)
    dest, err := net.Dial("tcp", destAddrPort)
    if err != nil {
        return nil, errors.New("dial dst: " + err.Error())
    }

    n, err = client.Write([]byte{0x05, 0x00, 0x00, 0x01, 0, 0, 0, 0, 0, 0})
    if err != nil {
        dest.Close()
        return nil, errors.New("write rsp: " + err.Error())
    }

    return dest, nil
}

func Socks5Forward(client, target net.Conn) {
    forward := func(src, dest net.Conn) {
        defer src.Close()
        defer dest.Close()
        io.Copy(src, dest)
    }
    go forward(client, target)
    go forward(target, client)
}
</code></pre>

