Go<pre><code>type Cond struct {
    noCopy noCopy
    // ​当​观察​或者​修改​等待​条件​的​时候​需要​加锁​
    L Locker
    // ​等待​队列​
    notify notifyList
    // ​辅助​结构​，​在​运行​时​检查​Cond​是否​被​复制​使用​
    checker copyChecker
}
func NewCond(l Locker) *Cond {
    return &amp;Cond{L: l}
}
func (c *Cond) Wait() {
    c.checker.check()
    // ​增加​到​等待​队列​中​
    t := runtime_notifyListAdd(&amp;c.notify)
    c.L.Unlock()
    // ​阻塞​休眠​直到​被​唤醒​
    runtime_notifyListWait(&amp;c.notify, t)
    c.L.Lock()
}
func (c *Cond) Signal() {
    c.checker.check()
    runtime_notifyListNotifyOne(&amp;c.notify)
}
func (c *Cond) Broadcast() {
    c.checker.check()
    runtime_notifyListNotifyAll(&amp;c.notify）
}
</code></pre>

