// ​互斥​锁​的​结构​，​包含​两个​字​段​
type Mutex struct {
key int32 // ​锁​是否​被​持有​的​标识​
sema int32 // ​信号量​专用​，​用以​阻塞​/​唤醒​goroutine
}
// ​保证​成功​在​val​上​增加​delta​的​值​
func xadd(val *int32, delta int32) (new int32) {
for {
v := *val
if cas(val, v, v+delta) {
return v + delta
}
}
panic("unreached")
}
// ​请求​锁​
func (m *Mutex) Lock() {
if xadd(&amp;m.key, 1) == 1 { //​标识​加​1，​如果​等于​1，​成功​获取​到​锁​
return
}
semacquire(&amp;m.sema) // ​否则​阻塞​等待​
}
func (m *Mutex) Unlock() {
if xadd(&amp;m.key, -1) == 0 { // ​将​标识​减去​1，​如果​等于​0，​则​没有​其它​等待​者​
return
}
semrelease(&amp;m.sema) // ​唤醒​其它​阻塞​的​goroutine
}
