}

// New ​创建​一个​指定​容量​的​环形​缓冲区​
// size: ​初始​容量​，​必须​大于​ 0
// ​返回​: ​初始化​完成​的​环形​缓冲区​实例​
func New[T any](size int64) *RingBuffer[T] {
    return &amp;RingBuffer[T]{
        content: &amp;buffer[T]{
            items: make([]T, size),
            head:  0,    // ​初始​头​指针​指向​位置​ 0
            tail:  0,    // ​初始​尾​指针​指向​位置​ 0
            mod:   size, // ​容量​用于​取模​运算​
        },
        len: 0, // ​初始​长度​为​ 0
    }
}

// Push ​向​缓冲区​尾部​插入​一个​元素​
// ​采用​先​移动​指针​再​检查​是否​需要​扩容​的​策略​
// ​若​缓冲区​已满​，​则​自动​扩容​为​原来​的​两倍​，​保证​ O(1) ​摊还​复杂度​
// item: ​要​插入​的​元素​
func (rb *RingBuffer[T]) Push(item T) {
    rb.mu.Lock()
    defer rb.mu.Unlock()

    // ​先​移动​尾​指针​到​下​一个​位置​
    rb.content.tail = (rb.content.tail + 1) % rb.content.mod

    // ​检查​是否​发生​环形​缓冲区​满​的​情况​（​尾​指针​追​上头​指针​）
    if rb.content.tail == rb.content.head {
        // ​缓冲区​已满​，​需要​扩容​
        size := rb.content.mod * 2
        newBuff := make([]T, size)

        // ​将​原有​数据​按​顺序​复制到​新​缓冲区​的​前半部​分​
        // ​从​ tail+1 ​开始​复制​，​保持​元素​的​逻辑​顺序​
        for i := int64(0); i &lt; rb.content.mod; i++ {
            idx := (rb.content.tail + i) % rb.content.mod
            newBuff[i] = rb.content.items[idx]
        }

        // ​创建​新​的​ buffer，​重置​头尾​指针​
        content := &amp;buffer[T]{
            items: newBuff,
            head:  0,              // ​头​指针​重置​为​ 0
            tail:  rb.content.mod, // ​尾​指针​指向​已​复制​数据​的​末尾​
            mod:   size,           // ​新​的​容量​
        }
        rb.content = content
    }

    // ​原子​递增​长度​计数器​
    atomic.AddInt64(&amp;rb.len, 1)
    // ​将​元素​写入​当前​尾​指针​位置​
    rb.content.items[rb.content.tail] = item
}

// Len ​返回​当前​缓冲区​元素​数量​
// ​使用​原子​操作​读取​，​保证​并发​安全​且​无需​加锁​
func (rb *RingBuffer[T]) Len() int64 {
    return atomic.LoadInt64(&amp;rb.len)
}

// Pop ​从​缓冲区​头部​弹​出​一个​元素​
// ​采用​ FIFO（​先进先出​）​策略​
// ​返回​: (​元素​值​, ​是否​成功​)，​若​缓冲区​为​空则​返回​ (​零值​, false)
func (rb *RingBuffer[T]) Pop() (T, bool) {
    rb.mu.Lock()
    defer rb.mu.Unlock()

    // ​检查​缓冲区​是否​为空​
    if rb.len == 0 {
        var t T // ​返回​类型​ T ​的​零值​
        return t, false
    }

    // ​移动​头​指针​到​下​一个​有效​元素​位置​
    rb.content.head = (rb.content.head + 1) % rb.content.mod
    item := rb.content.items[rb.content.head]

    // ​清空​已弹​出​的​位置​，​帮助​ GC ​回收​引用​类型​
    var t T
    rb.content.items[rb.content.head] = t

    // ​原子​递减​长度​计数器​
    atomic.AddInt64(&amp;rb.len, -1)
    return item, true
}

// PopN ​批量​弹​出​ n ​个​元素​，​返回​弹出​的​切片​
// ​提供​批量​操作​以​提高​性能​，​减少​锁​竞争​
// n: ​要弹​出​的​元素​数量​
// ​返回​: (​元素​切片​, ​是否​成功​)，​若​缓冲区​为​空则​返回​ (nil, false)
func (rb *RingBuffer[T]) PopN(n int64) ([]T, bool) {
    rb.mu.Lock()
    defer rb.mu.Unlock()

    // ​检查​缓冲区​是否​为空​
    if rb.len == 0 {
        return nil, false
    }

    content := rb.content

    // ​边界​检查​：​若​请求​数量​超过​当前​长度​，​则​只​弹出​全部​元素​
    if n &gt;= rb.len {
        n = rb.len
    }

    // ​原子​递减​长度​计数器​
    atomic.AddInt64(&amp;rb.len, -n)

    // ​预​分配​结果​切片​，​避免​动态​扩容​
    items := make([]T, n)

    // ​批量​复制​元素​，​处理​环形​边界​情况​
    for i := int64(0); i &lt; n; i++ {
        pos := (content.head + 1 + i) % content.mod
        items[i] = content.items[pos]

        // ​清空​已弹​出​位置​，​帮助​ GC ​回收​引用​类型​
        var t T
        content.items[pos] = t
    }

    // ​批量​移动​头​指针​
    content.head = (content.head + n) % content.mod

    return items, true
}
